from rank_bm25 import BM25Okapi
# Reciprocal Rank Fusion formula: RRF_score = sum(1.0 / (60 + rank))
def rrf_merge(bm25_ranks, vector_ranks):
    combined_scores = {}
    for doc_id, rank in bm25_ranks.items():
        combined_scores[doc_id] = combined_scores.get(doc_id, 0) + (1.0 / (60 + rank))
    for doc_id, rank in vector_ranks.items():
        combined_scores[doc_id] = combined_scores.get(doc_id, 0) + (1.0 / (60 + rank))
    return sorted(combined_scores.items(), key=lambda x: x[1], reverse=True)

